import {hasLegalOverlap} from './placement-rules.js';
import {saveArchive} from './archive-storage.js?v=exact-range-22894';
import {loadoutFiles,loadoutKey} from './loadouts.js';
import {features} from './conditions.js?v=neighborhood-20260914-3';
import {cardName} from './spoilers.js';
import {describeEffect,theoreticalStats,recipeStats,colorNames} from './card-stats.js';
import {attachCamera} from './camera.js';
import {penaltyRows,markedCells} from './penalty-display.js';
import {point as pt,polygon as poly,boundary} from './geometry.js';
const $=id=>document.getElementById(id), colors=['#101721','#ef7779','#e9ca72','#75c69c','#74ace3','#b497e0','#293b4c'];
let data,recipe,selected=new Set(),solution=null,worker=null;
const camera=attachCamera($('board'),k=>{const c=recipe?.cells.find(c=>key(c)===k);if(c&&c[2]>0&&c[2]<6)toggle(c)});
$('zoom-in').onclick=()=>camera.zoom(.8);$('zoom-out').onclick=()=>camera.zoom(1.25);$('fit').onclick=()=>camera.reset();
const key=c=>c.slice(0,2).join(',');
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const effects=a=>a.effects.map(describeEffect).join(' · ');
function reset(){$('team-loadout')?.remove();worker?.terminate();worker=null;$('stop').hidden=true;$('solve').disabled=false;solution=null;$('metrics').innerHTML='';$('card-stats').innerHTML='';$('status').textContent=$('objective').value==='stats'?'已选色块必须覆盖；未选择时自动搜索整张配方。':'点选色块，开始求解。'}
function list(){const q=$('search').value.toLowerCase(),current=recipe?.id||data.recipes[0].id;
 $('recipe').innerHTML=data.recipes.filter(r=>`${cardName(r)} ${r.internal} ${data.characters[r.character].name}`.toLowerCase().includes(q)).map(r=>{const supported=[...new Set(r.areas.flatMap(a=>a.effects.filter(e=>e.type===1).flatMap(e=>e.params.map(Number))))].filter(c=>c>=1&&c<=5&&c!==r.color).sort();return `<button type="button" role="option" data-recipe="${r.id}" aria-selected="${r.id===current}" tabindex="${r.id===current?0:-1}" style="--recipe-color:${colors[r.color]}"><span>${escape(r.internal)} · ${escape(cardName(r))}</span><span class="color-dots" aria-label="${supported.length?'可变为'+supported.map(c=>colorNames[c]).join('、'):'无变色'}">${supported.map(c=>`<i style="background:${colors[c]}" title="启用${colorNames[c]}"></i>`).join('')}</span></button>`}).join('');
 $('recipe').querySelectorAll('[data-recipe]').forEach(b=>b.onclick=()=>choose(b.dataset.recipe));
 const options=[...$('recipe').querySelectorAll('[data-recipe]')];if(options.length&&!options.some(b=>b.tabIndex===0))options[0].tabIndex=0;
}
$('recipe').addEventListener('keydown',e=>{const options=[...$('recipe').querySelectorAll('[data-recipe]')],index=options.indexOf(document.activeElement);let next;if(e.key==='ArrowDown')next=Math.min(options.length-1,index+1);else if(e.key==='ArrowUp')next=Math.max(0,index-1);else if(e.key==='Home')next=0;else if(e.key==='End')next=options.length-1;else return;e.preventDefault();if(options[next]){choose(options[next].dataset.recipe);options[next].focus()}});

function choose(id){const r=data.recipes.find(x=>x.id===Number(id));if(!r)throw Error('未知配方');reset();camera.newRecipe();recipe=r;selected=new Set();$('recipe').querySelectorAll('[data-recipe]').forEach(b=>{const active=Number(b.dataset.recipe)===r.id;b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1});$('title').textContent=cardName(r);const ch=data.characters[r.character];$('stats').innerHTML=`${ch.name} <span class="pill">${r.sr?'SR':'R'} / T${r.tier}</span><br>配方 ${r.internal}<br>有效粒子上限 <b>${Math.min(r.maxIota,ch.skills[2])}</b>　安全格 ${r.cells.length}`;const theoretical=recipeStats(r);$('stats').innerHTML+=`<div class="recipe-theory">理论威力 <b>${theoretical.power.toLocaleString('zh-CN')}</b><br>理论耐力 <b>${theoretical.fortitude.toLocaleString('zh-CN')}</b><small>粒子 999 · 全区域生效 · 无惩罚</small></div>`;$('skills').innerHTML=['灌注 Infusion','联觉 Synesthesia','角色粒子上限','越界耐性','重叠耐性','断连耐性','AugmentResolve'].map((n,i)=>`${n}：${ch.skills[i]}`).join('<br>');$('raw').textContent=JSON.stringify({recipe:r.internal,character:ch,recipeMaxIota:r.maxIota,challenges:r.challenges,rewards:r.rewards,baseCard:data.baseCards.find(c=>c.CardBaseId===data.recipeCardMapping[r.id]),bonusAreas:r.areas},null,2);render()}
function toggle(c){reset();let area=$('region').checked?recipe.areas.find(a=>a.cells.some(x=>key(x)===key(c))):null;let cells=area?.cells||[c],remove=cells.every(x=>selected.has(key(x)));for(const x of cells)remove?selected.delete(key(x)):selected.add(key(x));render()}
function render(){
 const visible=new Map(recipe.cells.map(c=>[key(c),c]));
 solution?.placements.forEach(p=>p.cells.forEach(c=>{if(!visible.has(key(c)))visible.set(key(c),[...c,0])}));
 const cells=[...visible.values()],points=cells.map(pt),xs=points.map(p=>p[0]),ys=points.map(p=>p[1]);
 camera.setBounds({x:Math.min(...xs)-35,y:Math.min(...ys)-35,w:Math.max(...xs)-Math.min(...xs)+70,h:Math.max(...ys)-Math.min(...ys)+70});
 const background=cells.map(c=>`<polygon points="${poly(c)}" fill="${colors[c[2]]}" fill-opacity=".45" stroke="#465369" stroke-width="1"/>`).join('');
 const pieces=(solution?.placements||[]).map((p,i)=>({...p,index:i,path:boundary(p.cells).path})).sort((a,b)=>b.cells.length-a.cells.length||a.index-b.index);
 const layers=pieces.map(p=>`<g data-particle="${p.index}"><path d="${p.path}" fill="${colors[p.color]}" fill-rule="evenodd"/><g class="piece-outline" pointer-events="none"><path d="${p.path}" fill="none" stroke="#101923" stroke-width="3.4" stroke-linejoin="round"/><path d="${p.path}" fill="none" stroke="#f1f6fa" stroke-opacity=".9" stroke-width="1.2" stroke-linejoin="round"/></g></g>`).join('');
 const owners=new Map();pieces.forEach(p=>p.cells.forEach(c=>owners.set(key(c),p.index)));
 const markers=cells.filter(c=>selected.has(key(c))).map(c=>{const [x,y]=pt(c);return `<circle cx="${x-8}" cy="${y-8}" r="2" fill="#edfff6" stroke="#163c31" stroke-width=".6"/>`}).join('');
 const labels=$('coords').checked?cells.map(c=>{const [x,y]=pt(c);return `<text x="${x}" y="${y+3}" text-anchor="middle" font-size="7" fill="#eaf3ff" stroke="#152536" stroke-width=".4" paint-order="stroke">${key(c)}</text>`}).join(''):pieces.map(p=>{const points=p.cells.map(pt),cx=points.reduce((a,b)=>a+b[0],0)/points.length,cy=points.reduce((a,b)=>a+b[1],0)/points.length,[x,y]=points.reduce((a,b)=>(a[0]-cx)**2+(a[1]-cy)**2<(b[0]-cx)**2+(b[1]-cy)**2?a:b);return `<text x="${x}" y="${y+3.5}" text-anchor="middle" font-size="10" font-weight="600" fill="#152536">${p.index+1}</text>`}).join('');
 const hits=cells.map(c=>`<polygon data-cell="${key(c)}" data-piece="${owners.get(key(c))??''}" points="${poly(c)}" fill="transparent" stroke="none"/>`).join('');
 const marked=markedCells(recipe,solution?.placements||[]);
 const patterns=`<defs><pattern id="unsafe-stripes" width="8" height="8" patternUnits="userSpaceOnUse" patternTransform="rotate(35)"><rect width="8" height="8" fill="#ff334d" fill-opacity=".1"/><path d="M0 0V8" stroke="#ff2345" stroke-opacity=".5" stroke-width="3"/></pattern><pattern id="overlap-dots" width="7" height="7" patternUnits="userSpaceOnUse"><rect width="7" height="7" fill="#ff334d" fill-opacity=".1"/><circle cx="3.5" cy="3.5" r="1.6" fill="#ff2345" fill-opacity=".65"/></pattern></defs>`;
 const overlays=['unsafe','overlap'].map(type=>marked[type].map(k=>`<polygon points="${poly(k.split(',').map(Number))}" fill="url(#${type==='unsafe'?'unsafe-stripes':'overlap-dots'})"/>`).join('')).join('');
 $('board').innerHTML=patterns+background+layers+`<g pointer-events="none">${overlays}${markers}${labels}</g><path id="hover-outline" fill="none" stroke="#fffbb1" stroke-width="3" stroke-linejoin="round" pointer-events="none"/>`+hits;
 const highlight=e=>{const id=e.target.closest('[data-piece]')?.dataset.piece,p=pieces.find(p=>String(p.index)===id);$('hover-outline').setAttribute('d',p?.path||'')};
 $('board').onpointermove=e=>{if(!e.buttons)highlight(e)};$('board').onpointerleave=()=>{$('hover-outline')?.setAttribute('d','')};$('board').onpointerdown=()=>{$('hover-outline')?.setAttribute('d','')};
 $('count').textContent=`${selected.size} 格已选`;
 $('areas').innerHTML=recipe.areas.map((a,i)=>`<button data-area="${i}" class="${(solution?.objective==='stats'?(solution.score.activeAreas.includes(i)||a.cells.every(c=>selected.has(key(c)))):a.cells.every(c=>selected.has(key(c))))?'selected':''}"><b>${i+1}. ${a.cells.length} 格</b><br>${escape(effects(a))}</button>`).join('');
 $('areas').querySelectorAll('button').forEach(b=>b.onclick=()=>{reset();const a=recipe.areas[+b.dataset.area],remove=a.cells.every(c=>selected.has(key(c)));a.cells.forEach(c=>remove?selected.delete(key(c)):selected.add(key(c)));render()});
}
function update(result){if(!hasLegalOverlap(result.placements))throw Error('该旧方案存在四重重叠，无法使用，请重新求解。');solution=result;const f=features(recipe,result);const stats=theoreticalStats(recipe,result),num=n=>n.toLocaleString('zh-CN');$('card-stats').innerHTML=`<div class="card-stats-title">当前解 · 理论属性</div><div class="card-stat-values"><div><strong>${num(stats.power)}</strong><span>威力</span></div><div><strong>${num(stats.fortitude)}</strong><span>耐力</span></div></div><p>总属性 ${num(stats.power+stats.fortitude)}<br>${f.slots} 特质槽 · 范围 ${f.range}（1＋${f.left}＋${f.right}）<br>可选${f.colors.map(c=>colorNames[c]).join('、')}<br>全部粒子 999 · 已计入诅咒惩罚<br>${stats.strikes} 次惩罚 · 保留 ${[100,88.89,55.56][stats.strikes]??0}%</p>`;const s=result.score,rows=penaltyRows(s,data.characters[recipe.character].skills,recipe);$('metrics').innerHTML=[['总惩罚',s.total],['粒子',`${result.placements.length}/${s.limit}`]].map(([n,v])=>`<div class="metric ${n==='总惩罚'&&v>0?'penalty-positive':''}"><strong>${v}</strong>${n}</div>`).join('')+rows.map(r=>`<div class="metric ${r.net>0?'penalty-positive':''}"><strong>${r.raw} <span class="deduction">− ${r.skill}</span></strong>${r.name}<small>${r.extra?'区域豁免 − '+r.extra+'<br>':''}${r.hint}</small></div>`).join('')+`<p class="metric-help">原始数量 − 技能耐性，最低计为 0。<br>纹路标记抵消前的越界与重叠位置。</p>`;render()}

function solve(){const archiveRecipe=recipe,archiveNoTier3=$('no-tier-three').checked;const objective=$('objective').value,initialSolution=solution;if(objective!=='stats'&&!selected.size){$('status').textContent='请先点选至少一个色块。';return}reset();$('solve').disabled=true;$('stop').hidden=false;$('status').textContent='正在生成形状放置，搜索覆盖方案…';worker=new Worker('worker.js?v=snapshot-64812-credit',{type:'module'});worker.onmessage=({data:m})=>{if(m.type==='archive'){saveArchive(archiveRecipe,archiveNoTier3,m.entries).catch(()=>{$('status').textContent='本地方案保存失败，当前计算结果仍可使用。'});return;}if(m.result)update(m.result);if(m.type==='done'){worker.terminate();worker=null;$('solve').disabled=false;$('stop').hidden=true;$('status').textContent=objective==='stats'?(solution?.provenOptimal?'已达到总属性理论上限。':`搜索完成：当前最佳总属性 ${solution?.value?.toLocaleString('zh-CN')??0}，尚未证明全局最优。`):solution?.score.total===0?'已找到 0 惩罚方案，达到惩罚理论下界。':`搜索完成：当前最佳 ${solution?.score.total??'—'} 惩罚，尚未证明全局最优。`}else if(m.type==='error'){$('status').textContent=m.message;$('solve').disabled=false;$('stop').hidden=true}else $('status').textContent=objective==='stats'?`搜索中 · 已尝试 ${m.iterations||0} 组 · 总属性 ${solution?.value?.toLocaleString('zh-CN')??0}`:`搜索中 · 已尝试 ${m.iterations||0} 组 · 当前 ${solution?.score.total??'—'} 惩罚`};worker.onerror=e=>{$('status').textContent='求解失败：'+e.message;$('solve').disabled=false;$('stop').hidden=true};worker.postMessage({objective,initialSolution,minRange:Number($('min-range').value),minSlots:Number($('min-slots').value),cardColor:Number($('card-color').value),excludeTier3:$('no-tier-three').checked,seed:Date.now(),recipe,iotas:data.iotas,skills:data.characters[recipe.character].skills,targets:[...selected],timeMs:Number($('duration').value)*1000})}
window.addEventListener('card-name-visibility',()=>{if(!data)return;list();if(recipe)$('title').textContent=cardName(recipe)});
$('no-tier-three').onchange=()=>{reset();render()};
$('objective').onchange=()=>{reset();$('solve').textContent=$('objective').value==='stats'?'求解总属性最大 ↗':'求解最少惩罚 ↗';$('status').textContent=$('objective').value==='stats'?'已选色块必须覆盖；未选择时自动搜索整张配方。':'点选色块，开始求解。'};$('search').oninput=list;$('coords').onchange=render;$('all').onclick=()=>{reset();selected=new Set(recipe.cells.filter(c=>c[2]>0&&c[2]<6).map(key));render()};$('clear').onclick=()=>{reset();selected.clear();render()};$('solve').onclick=solve;$('stop').onclick=()=>{worker?.terminate();worker=null;$('solve').disabled=false;$('stop').hidden=true;$('status').textContent='搜索已停止，保留当前最佳方案。'};
try{data=await(await fetch('data.json')).json();list();choose(data.recipes[0].id);
const params=new URLSearchParams(location.search),savedId=params.get('saved');$('min-range').value=String(Math.max(1,Math.min(5,Number(params.get('range'))||1)));$('min-slots').value=String(Math.max(0,Math.min(3,Number(params.get('slots'))||0)));$('card-color').value=String(Math.max(0,Math.min(5,Number(params.get('color'))||0)));
if(savedId!==null){const ranked=await(await fetch('ranking-data.json?v=snapshot-64812-credit')).json(),entry=ranked.rows.find(r=>r.id===Number(savedId));if(entry){choose(entry.id);$('objective').value='stats';$('objective').onchange();const k=$('min-slots').value+':'+$('card-color').value+':'+$('min-range').value,i=entry.conditions?.[k],saved=i>=0?entry.variants[i]:k==='0:0:1'?entry.result:null;if(saved){update({...saved,objective:'stats'});$('status').textContent='已加载对应槽位／颜色／范围条件的排名方案。'}else $('status').textContent='此条件下尚无已知方案，请调整条件或开始搜索。';$('recipe').querySelector('[aria-selected="true"]')?.scrollIntoView({block:'nearest'});}else $('status').textContent='该配方的排名方案尚未收录。';}
if(params.has('team')){const loadout=loadoutKey(params.get('loadout'),'original');const team=await(await fetch(loadoutFiles[loadout]+'?v=snapshot-64812-credit')).json(),position=Number(params.get('team')),card=team.cards.find(c=>c.position===position);if(!card)throw Error('未知的五卡方案阶段');choose(card.id);$('objective').value='stats';$('objective').onchange();update({...card.crafting,objective:'stats'});const info=document.createElement('section');info.id='team-loadout';info.className='team-loadout';info.innerHTML=`<a href="team.html?loadout=${loadout}">← 返回五卡方案</a><p>第 ${card.position} 阶段 · 成品${colorNames[card.color]}<br>额外左范围 ${card.left}／右范围 ${card.right}</p><b>装备技能</b><ul>${card.traits.map(t=>`<li>${escape(t.name)}</li>`).join('')}</ul>`;$('card-stats').before(info);$('status').textContent='已加载五卡组合的完整拼法。修改色块或重新求解后，需重新核对配装条件。';$('recipe').querySelector('[aria-selected="true"]')?.scrollIntoView({block:'nearest'});}
const rankingLink=()=>{$('ranking-link').href='ranking.html?page='+Math.max(1,Number(params.get('page'))||1)+'&slots='+$('min-slots').value+'&color='+$('card-color').value+'&range='+$('min-range').value};rankingLink();$('min-slots').onchange=$('card-color').onchange=$('min-range').onchange=()=>{$('objective').value='stats';$('objective').onchange();render();rankingLink()};
if(document.modelContext?.registerTool){const context=document.modelContext;for(const tool of [{name:'get_recipe_solver_state',description:'Read current recipe, selected target cells and solution.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({recipe:recipe.internal,targets:[...selected],solution})},{name:'select_recipe_targets',description:'Choose a recipe and set target cells in the visible solver.',inputSchema:{type:'object',properties:{recipeId:{type:'integer'},targets:{type:'array',items:{type:'string'}}},required:['recipeId','targets'],additionalProperties:false},execute:input=>{const r=data.recipes.find(r=>r.id===input.recipeId);if(!r||!Array.isArray(input.targets)||input.targets.some(k=>!r.cells.some(c=>key(c)===k&&c[2]>0&&c[2]<6)))throw Error('Invalid recipe or target');choose(input.recipeId);selected=new Set(input.targets);render();return {recipe:recipe.internal,targets:[...selected]}}}])Promise.resolve(context.registerTool(tool)).catch(console.error)}}catch(e){$('status').textContent='无法加载数据：'+e.message}